/**
 * ==========================================================
 * TO DO SOLO
 * LIGHTWEIGHT CONFETTI
 * ==========================================================
 */

(function () {

    function launchConfetti(
        options = {}
    ) {

        const count =
            options.count || 80;


        const duration =
            options.duration || 1800;


        const canvas =
            document.createElement(
                "canvas"
            );


        canvas.style.position =
            "fixed";

        canvas.style.inset =
            "0";

        canvas.style.width =
            "100%";

        canvas.style.height =
            "100%";

        canvas.style.pointerEvents =
            "none";

        canvas.style.zIndex =
            "99999";


        document.body.appendChild(
            canvas
        );


        const context =
            canvas.getContext(
                "2d"
            );


        const particles =
            [];


        function resize() {

            canvas.width =
                window.innerWidth;

            canvas.height =
                window.innerHeight;

        }


        resize();


        const colors = [
            "#6366F1",
            "#22C55E",
            "#F59E0B",
            "#EF4444",
            "#3B82F6",
            "#EC4899",
        ];


        for (
            let index = 0;
            index < count;
            index++
        ) {

            particles.push({

                x:
                    Math.random() *
                    canvas.width,

                y:
                    -10,

                size:
                    4 +
                    Math.random() * 6,

                speed:
                    2 +
                    Math.random() * 5,

                drift:
                    -2 +
                    Math.random() * 4,

                rotation:
                    Math.random() *
                    Math.PI,

                rotationSpeed:
                    -0.15 +
                    Math.random() * 0.3,

                color:
                    colors[
                        Math.floor(
                            Math.random() *
                            colors.length
                        )
                    ],

            });

        }


        const start =
            performance.now();


        function frame(now) {

            const elapsed =
                now - start;


            context.clearRect(
                0,
                0,
                canvas.width,
                canvas.height
            );


            particles.forEach(
                particle => {

                    particle.y +=
                        particle.speed;

                    particle.x +=
                        particle.drift;

                    particle.rotation +=
                        particle.rotationSpeed;


                    context.save();


                    context.translate(
                        particle.x,
                        particle.y
                    );


                    context.rotate(
                        particle.rotation
                    );


                    context.fillStyle =
                        particle.color;


                    context.fillRect(
                        -particle.size / 2,
                        -particle.size / 2,
                        particle.size,
                        particle.size
                    );


                    context.restore();

                }
            );


            if (
                elapsed <
                duration
            ) {

                requestAnimationFrame(
                    frame
                );

            }
            else {

                canvas.remove();

            }

        }


        requestAnimationFrame(
            frame
        );

    }


    window.ToDoSoloConfetti =
        launchConfetti;

})();